<script setup lang="ts">
import { computed,ref } from 'vue';
import {catalogCategories} from './catalog-categories';
import {docsComponents} from './docs-components';
const props=defineProps<{active?:string}>();
const search=ref(''); const mobileOpen=ref(false);
const sections=computed(()=>catalogCategories.map(c=>({...c,components:docsComponents.filter(x=>x.category===c.id&&x.name.toLowerCase().includes(search.value.toLowerCase()))})).filter(c=>!search.value||c.components.length||c.title.toLowerCase().includes(search.value.toLowerCase())));
</script>
